import axios from "axios";
import type { Note, Tag } from "@/types/note";
import type User from "@/types/user";

/**
 * CLIENT-SIDE axios instance
 * Works in browser and on Vercel
 */
const clientApi = axios.create({
  baseURL: process.env.NEXT_PUBLIC_API_URL,
  withCredentials: true,
});

/* ================= NOTES ================= */

export interface FetchNotesResponse {
  notes: Note[];
  totalPages: number;
}

export interface CreateNotePayload {
  title: string;
  content: string;
  tag: Tag;
}

export const fetchNotes = async (
  query: string,
  currentPage: number,
  tag?: string
): Promise<FetchNotesResponse> => {
  const params: Record<string, string | number> = {
    search: query,
    page: currentPage,
    perPage: 12,
  };

  // ❗ НЕ передаємо tag=all
  if (tag && tag !== "all") {
    params.tag = tag;
  }

  const { data } = await clientApi.get<FetchNotesResponse>("/notes", {
    params,
  });

  return data;
};

export const fetchNoteById = async (noteId: string): Promise<Note> => {
  const { data } = await clientApi.get<Note>(`/notes/${noteId}`);
  return data;
};

export const createNote = async (
  payload: CreateNotePayload
): Promise<{ note: Note }> => {
  const { data } = await clientApi.post<{ note: Note }>("/notes", payload);
  return data;
};

export const deleteNote = async (noteId: string): Promise<{ note: Note }> => {
  const { data } = await clientApi.delete<{ note: Note }>(`/notes/${noteId}`);
  return data;
};

/* ================= AUTH ================= */

export interface RegisterRequest {
  email: string;
  password: string;
  username: string;
}

export interface LoginRequest {
  email: string;
  password: string;
}

export interface SessionResponse {
  success: boolean;
}

export const register = async (body: RegisterRequest): Promise<User> => {
  const { data } = await clientApi.post<User>("/auth/register", body);
  return data;
};

export const login = async (body: LoginRequest): Promise<User> => {
  const { data } = await clientApi.post<User>("/auth/login", body);
  return data;
};

export const checkSession = async (): Promise<boolean> => {
  const { data } = await clientApi.get<SessionResponse>("/auth/session");
  return data.success;
};

export const logOut = async (): Promise<void> => {
  await clientApi.post("/auth/logout");
};

/* ================= USER ================= */

export const getMe = async (): Promise<User> => {
  const { data } = await clientApi.get<User>("/users/me");
  return data;
};

export const patchMe = async (username: string): Promise<User> => {
  const { data } = await clientApi.patch<User>("/users/me", {
    username,
  });
  return data;
};
